    fn hex_encode(bytes: &[u8]) -> String {
        const LUT: &[u8; 16] = b"0123456789abcdef";
        let mut output = String::with_capacity(bytes.len() * 2);
        for byte in bytes {
            output.push(LUT[(byte >> 4) as usize] as char);
            output.push(LUT[(byte & 0x0f) as usize] as char);
        }
        output
    }

