        write_test_sudoku_mux_frame(&mut *stream, TEST_SUDOKU_MUX_FRAME_DATA, 1, b"helloA");
        write_test_sudoku_mux_frame(&mut *stream, TEST_SUDOKU_MUX_FRAME_CLOSE, 1, &[]);

